// Writes src/lib/api/bindings/index.ts re-exporting every ts-rs generated type.
import { readdirSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const dir = join(dirname(fileURLToPath(import.meta.url)), "..", "src", "lib", "api", "bindings");
const files = readdirSync(dir)
  .filter((f) => f.endsWith(".ts") && f !== "index.ts")
  .sort();
const lines = [
  "// Generated by scripts/gen-bindings-index.mjs. Do not edit.",
  ...files.map((f) => `export type { ${f.replace(/\.ts$/, "")} } from "./${f.replace(/\.ts$/, "")}";`),
  "",
];
writeFileSync(join(dir, "index.ts"), lines.join("\n"));
console.log(`bindings index: ${files.length} types`);
